  mn('P-S-P-V', 'ECI runs: <b>P</b>arliament, <b>S</b>tate Legislatures, <b>P</b>resident, <b>V</b>ice-President: “<b>P</b>eople <b>S</b>elect <b>P</b>resident and <b>V</b>P.” Top four offices = ECI; local bodies = SEC.'),
